{
  "summary": "Add a bounded ActivityHistory.recent(int limit) overload with immutable detached results and focused regression coverage.",
  "ui_goal": "No change needed.",
  "backend_goal": "Implement ActivityHistory.recent(int limit), validating against configured capacity and selecting the newest retained events in chronological order without changing history state or the existing no-argument method.",
  "tests_goal": "Extend ActivityHistoryTest with regression coverage for limit validation, newest-event selection, chronological ordering, immutable detached results, and preservation of existing history behavior.",
  "worker_files": {
    "ui": [],
    "backend": [
      "src/main/java/dev/atmcompanion/activity/ActivityHistory.java"
    ],
    "tests": [
      "src/test/java/dev/atmcompanion/activity/ActivityHistoryTest.java"
    ]
  },
  "interface_contracts": [
    {
      "name": "ActivityHistory.recent(int limit)",
      "owner": "backend",
      "consumer_roles": [
        "tests"
      ],
      "contract": "Add public List<ActivityEvent> recent(int limit) to ActivityHistory. Accept 1 <= limit <= configured capacity; otherwise throw IllegalArgumentException, including when history is empty. Return min(limit, retained event count) newest retained events in their existing chronological order as an immutable detached list. Subsequent history changes must not alter a returned list. Calling this overload must not modify history state. Preserve the existing recent() signature and behavior."
    }
  ],
  "provider_changes": [],
  "acceptance": [
    "The overload accepts exactly limits from 1 through configured capacity and rejects all others with IllegalArgumentException.",
    "Empty, partially populated, full, and evicted histories return at most the newest requested number of retained events in chronological order.",
    "Returned lists are immutable and detached from subsequent history changes.",
    "History state and existing recent() behavior remain unchanged."
  ],
  "worker_acceptance": {
    "ui": [],
    "backend": [
      "Implement the public overload and validate limits against configured capacity rather than retained event count.",
      "Select the newest bounded suffix of retained events while preserving chronological order.",
      "Return an immutable detached list without mutating history or altering the no-argument method."
    ],
    "tests": [
      "Cover valid boundaries 1 and configured capacity, plus negative, zero, and above-capacity limits, including validation on empty history.",
      "Cover empty, partially populated, full, and evicted histories with assertions for count, event selection, and chronological order.",
      "Assert returned-list mutation is rejected and later history changes do not affect previously returned results.",
      "Assert calls to the overload preserve retained history and existing no-argument recent() results."
    ]
  }
}

