@Test void rejectsInvalid(){assertThrows(RuntimeException.class,()->new ActivityHistory(0));assertThrows(RuntimeException.class,()->new ActivityHistory(257));assertThrows(RuntimeException.class,()->new ActivityHistory(1).append(null));}

@Test void limitedRecentRejectsInvalidLimitsEvenWhenEmpty() {
 for (int count : new int[]{0, 1}) {
  var h = new ActivityHistory(3);
  if (count == 1) h.append(e("minecraft:a"));
  var retained = List.copyOf(h.recent());
  for (int limit : new int[]{-1, 0, 4}) {
   assertThrows(IllegalArgumentException.class, () -> h.recent(limit));
   assertEquals(count, h.size());
   assertEquals(retained, h.recent());
  }
 }
}

@Test void limitedRecentAcceptsBoundariesOnEmptyHistory() {
 var h = new ActivityHistory(3);
 assertLimitedRecentPreservesHistory(h, 1, List.of());
 assertLimitedRecentPreservesHistory(h, 3, List.of());
 var snapshot = h.recent(3);
 assertThrows(UnsupportedOperationException.class, () -> snapshot.add(e("minecraft:a")));
 h.append(e("minecraft:a"));
 assertEquals(List.of(), snapshot);
 assertEquals(List.of(e("minecraft:a")), h.recent());
 assertEquals(1, h.size());
}

@Test void limitedRecentSelectsNewestEventsInChronologicalOrder() {
 var h = new ActivityHistory(3);
 var a = e("minecraft:a");
 var b = e("minecraft:b");
 var c = e("minecraft:c");
 var d = e("minecraft:d");
 h.append(a);
 h.append(b);
 assertLimitedRecentPreservesHistory(h, 1, List.of(b));
 assertLimitedRecentPreservesHistory(h, 2, List.of(a, b));
 assertLimitedRecentPreservesHistory(h, 3, List.of(a, b));
 assertEquals(List.of(a, b), h.recent());
 assertEquals(2, h.size());

 h.append(c);
 assertLimitedRecentPreservesHistory(h, 1, List.of(c));
 assertLimitedRecentPreservesHistory(h, 2, List.of(b, c));
 assertLimitedRecentPreservesHistory(h, 3, List.of(a, b, c));
 assertEquals(List.of(a, b, c), h.recent());
 assertEquals(3, h.size());

 h.append(d);
 assertLimitedRecentPreservesHistory(h, 1, List.of(d));
 assertLimitedRecentPreservesHistory(h, 2, List.of(c, d));
 assertLimitedRecentPreservesHistory(h, 3, List.of(b, c, d));
 assertEquals(List.of(b, c, d), h.recent());
 assertEquals(3, h.size());
}

@Test void limitedRecentResultsAreImmutableAndDetached() {
 var h = new ActivityHistory(3);
 var a = e("minecraft:a");
 var b = e("minecraft:b");
 var c = e("minecraft:c");
 var d = e("minecraft:d");
 h.append(a);
 h.append(b);
 var partial = h.recent(3);
 h.append(c);
 assertEquals(List.of(a, b), partial);
 var newest = h.recent(1);
 var limited = h.recent(2);
 var full = h.recent(3);
 for (var snapshot : List.of(partial, newest, limited, full)) {
  assertThrows(UnsupportedOperationException.class, () -> snapshot.add(d));
  assertThrows(UnsupportedOperationException.class, () -> snapshot.set(0, d));
  assertThrows(UnsupportedOperationException.class, () -> snapshot.remove(0));
  assertThrows(UnsupportedOperationException.class, snapshot::clear);
 }
 assertEquals(List.of(a, b, c), h.recent());
 assertEquals(3, h.size());

 h.append(d);
 assertEquals(List.of(a, b), partial);
 assertEquals(List.of(c), newest);
 assertEquals(List.of(b, c), limited);
 assertEquals(List.of(a, b, c), full);
 assertEquals(List.of(b, c, d), h.recent());
 assertEquals(3, h.size());

 h.clear();
 assertLimitedRecentPreservesHistory(h, 3, List.of());
 assertEquals(0, h.size());
 h.append(d);
 assertLimitedRecentPreservesHistory(h, 1, List.of(d));
 assertEquals(List.of(a, b), partial);
 assertEquals(List.of(c), newest);
 assertEquals(List.of(b, c), limited);
 assertEquals(List.of(a, b, c), full);
 assertEquals(List.of(d), h.recent());
 assertEquals(1, h.size());
}

private void assertLimitedRecentPreservesHistory(ActivityHistory history, int limit, List<ActivityEvent> expected) {
 var retained = List.copyOf(history.recent());
 int retainedCount = history.size();
 var actual = history.recent(limit);
 assertEquals(expected, actual);
 assertEquals(Math.min(limit, retainedCount), actual.size());
 assertEquals(retainedCount, history.size());
 assertEquals(retained, history.recent());
}

